
.览 {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: #0b0f14;
}

/* 台子比窗口矮一条 —— 底下的预览条要占位。合窗.ts 量的是 window.innerHeight, 会把这
   一条也算进去, 于是缩放算得略大一点点。手机竖屏下 320×420 本来就装得下, 缩放恒为 1,
   所以这点误差碰不到。真碰到的只有极窄的窗口, 那时候也看不出来。 */
.览__台 {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.览__条 {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: #141a22;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

.览__名 {
  margin-right: 4px;
  color: #4d5866;
  font-size: 11px;
  letter-spacing: 0.16em;
}

.览__隙 {
  flex: 1;
}

.览__钮 {
  min-height: 30px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.04);
  color: #8e99a6;
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;

  &.is-开 {
    border-color: rgba(127, 227, 255, 0.4);
    background: rgba(127, 227, 255, 0.14);
    color: #a8ecff;
  }

  &.is-层 {
    color: #6f7a87;
    font-variant-numeric: tabular-nums;
  }
}

/* 弹出来的提示。挂到 body 上, 所以不能用 scoped。 */
.览吐 {
  position: fixed;
  right: 12px;
  bottom: 56px;
  z-index: 999;
  max-width: min(78vw, 340px);
  padding: 9px 13px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 9px;
  background: #1b222c;
  color: #cfd7e0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 13px;
  line-height: 1.5;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.5);
  animation: th-toast-in 0.2s ease-out both;

  &.is-错 {
    border-color: rgba(255, 138, 128, 0.4);
    color: #ffb4ac;
  }

  &.is-成 {
    border-color: rgba(127, 227, 255, 0.36);
    color: #a8ecff;
  }

  &.is-警 {
    border-color: rgba(255, 213, 128, 0.36);
    color: #ffd580;
  }
}

@keyframes th-toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
